// Reference: float -> plain decimal digit string -> quantize(2, HALF_EVEN) -> grouped
export function shortestPlainDecimal(x){
  // returns {sign, intDigits:string, fracDigits:string} exact value of String(x) shortest repr
  if (!isFinite(x)) throw new Error('nonfinite');
  const neg = x < 0 || Object.is(x,-0);
  let s = Math.abs(x).toString();           // shortest round-trip, JS notation
  let mant = s, exp = 0;
  const ei = s.indexOf('e');
  if (ei >= 0){ mant = s.slice(0,ei); exp = parseInt(s.slice(ei+1),10); }
  let dot = mant.indexOf('.');
  let digits;
  if (dot >= 0){ digits = mant.slice(0,dot)+mant.slice(dot+1); exp -= (mant.length-dot-1); }
  else digits = mant;
  // value = digits * 10^exp
  let intPart, fracPart;
  if (exp >= 0){ intPart = digits + '0'.repeat(exp); fracPart = ''; }
  else {
    const k = -exp;
    if (k >= digits.length){ intPart='0'; fracPart='0'.repeat(k-digits.length)+digits; }
    else { intPart = digits.slice(0,digits.length-k); fracPart = digits.slice(digits.length-k); }
  }
  intPart = intPart.replace(/^0+(?=\d)/,'');
  return {neg, intPart, fracPart};
}
export function quantize2HalfEven({neg,intPart,fracPart}){
  let f = (fracPart+'00').slice(0,2);
  const rest = fracPart.slice(2);
  let all = intPart + f;                 // integer scaled by 100
  if (rest.length){
    const first = rest.charCodeAt(0)-48;
    const restNonZero = /[1-9]/.test(rest.slice(1));
    let up = false;
    if (first > 5) up = true;
    else if (first === 5){ up = restNonZero ? true : ((all.charCodeAt(all.length-1)-48) % 2 === 1); }
    if (up){ all = (function inc(s){ let a=s.split(''); let i=a.length-1;
        for(;i>=0;i--){ if(a[i]==='9'){a[i]='0';} else {a[i]=String.fromCharCode(a[i].charCodeAt(0)+1); break;} }
        return i<0 ? '1'+a.join('') : a.join(''); })(all); }
  }
  all = all.replace(/^0+(?=\d)/,'');
  while (all.length < 3) all = '0'+all;
  const ip = all.slice(0,-2), fp = all.slice(-2);
  return {neg, ip, fp, digits: all.length};
}
export function group(ip){ return ip.replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
export function fmt(x){
  if (Number.isNaN(x)) throw new Error('NaN cmp');
  if (!isFinite(x)) return (x<0?'-':'')+'$∞';
  const q = quantize2HalfEven(shortestPlainDecimal(x));
  if (q.digits > 28) throw new Error('InvalidOperation');
  return (q.neg?'-':'')+'$'+group(q.ip)+'.'+q.fp;
}
